 1→import { create } from 'zustand';
 2→
 3→const API_BASE_URL = import.meta.env.VITE_API_URL || 'http://localhost:8000';
 4→
 5→interface User {
 6→    id: string;
 7→    email: string;
 8→    name: string | null;
 9→}
10→
11→interface AuthState {
12→    token: string | null;
13→    user: User | null;
14→    isSessionExpired: boolean;
15→    setAuth: (token: string, user: User) => void;
16→    setSessionExpired: () => void;
17→    logout: () => void;
18→    isAuthenticated: () => boolean;
19→}
20→
21→// Initialize from localStorage
22→function getStoredAuth(): { token: string | null; user: User | null } {
23→    try {
24→        const token = localStorage.getItem('auth_token');
25→        const userStr = localStorage.getItem('auth_user');
26→        const user = userStr ? JSON.parse(userStr) : null;
27→        return { token, user };
28→    } catch {
29→        return { token: null, user: null };
30→    }
31→}
32→
33→export const useAuthStore = create<AuthState>((set, get) => ({
34→    ...getStoredAuth(),
35→    isSessionExpired: false,
36→    setAuth: (token: string, user: User) => {
37→        localStorage.setItem('auth_token', token);
38→        localStorage.setItem('auth_user', JSON.stringify(user));
39→        set({ token, user, isSessionExpired: false });
40→    },
41→    setSessionExpired: () => {
42→        // Guard against cascading calls from multiple simultaneous 401s
43→        if (get().isSessionExpired) return;
44→        set({ isSessionExpired: true });
45→    },
46→    logout: () => {
47→        localStorage.removeItem('auth_token');
48→        localStorage.removeItem('auth_user');
49→        set({ token: null, user: null, isSessionExpired: false });
50→    },
51→    isAuthenticated: () => {
52→        const state = get();
53→        return Boolean(state.token && state.user);
54→    },
55→}));
56→
57→// Utility function to get auth headers
58→export function getAuthHeaders(): Record<string, string> {
59→    const token = useAuthStore.getState().token;
60→    return token ? { Authorization: `Bearer ${token}` } : {};
61→}
62→
63→// Login function that opens a popup for OAuth and listens for the token via postMessage.
64→// Returns a cleanup function; call it if the component unmounts while the popup is open.
65→export function initiateLogin(): { popupBlocked: boolean; cleanup: () => void } {
66→    const popup = window.open(
67→        `${API_BASE_URL}/auth/login?popup=1`,
68→        'auth-popup',
69→        'width=500,height=600,menubar=no,toolbar=no'
70→    );
71→
72→    if (!popup) {
73→        return { popupBlocked: true, cleanup: () => {} };
74→    }
75→
76→    const handleMessage = (event: MessageEvent) => {
77→        const apiOrigin = new URL(API_BASE_URL).origin;
78→        if (event.origin !== apiOrigin) return;
79→        const { access_token, user } = event.data ?? {};
80→        if (access_token && user) {
81→            useAuthStore.getState().setAuth(access_token, user);
82→            popup.close();
83→            window.removeEventListener('message', handleMessage);
84→        }
85→    };
86→    window.addEventListener('message', handleMessage);
87→
88→    return {
89→        popupBlocked: false,
90→        cleanup: () => window.removeEventListener('message', handleMessage),
91→    };
92→}
