20→class ErrorBoundary extends Component<{ children: ReactNode }, { error: Error | null }> {
21→    state = { error: null as Error | null };
22→
23→    static getDerivedStateFromError(error: Error) {
24→        return { error };
25→    }
26→
27→    render() {
28→        if (this.state.error) {
29→            return (
30→                <div style={{ padding: 24, fontFamily: 'sans-serif', maxWidth: 600 }}>
31→                    <h1 style={{ color: '#b91c1c' }}>Something went wrong</h1>
32→                    <pre style={{ background: '#fef2f2', padding: 16, overflow: 'auto' }}>
33→                        {this.state.error.message}
34→                    </pre>
35→                    <p style={{ color: '#666' }}>Check the browser console for the full stack.</p>
36→                </div>
37→            );
38→        }
39→        return this.props.children;
40→    }
41→}
42→
43→const queryClient = new QueryClient({
44→    defaultOptions: {
45→        queries: {
46→            staleTime: 1000 * 60 * 5, // 5 minutes
47→            retry: (failureCount, error) => {
48→                // Never retry auth errors
49→                if (error instanceof SessionExpiredError) return false;
50→                return failureCount < 1;
51→            },
52→        },
53→    },
54→});
55→
56→// When session expires, cancel all in-flight queries.
57→// When session is restored, invalidate all queries to refetch.
58→useAuthStore.subscribe((state, prev) => {
59→    if (state.isSessionExpired && !prev.isSessionExpired) {
60→        queryClient.cancelQueries();
61→    }
62→    if (!state.isSessionExpired && prev.isSessionExpired) {
63→        queryClient.invalidateQueries();
64→    }
65→});
66→
67→const rootElement = document.getElementById('root');
68→if (!rootElement) throw new Error('Root element not found');
69→
70→createRoot(rootElement).render(
71→    <StrictMode>
72→        <ErrorBoundary>
73→            <QueryClientProvider client={queryClient}>
74→                <BrowserRouter basename={routerBasename}>
75→                    <App />
76→                </BrowserRouter>
77→                <ReactQueryDevtools initialIsOpen={false} />
78→            </QueryClientProvider>
79→        </ErrorBoundary>
80→    </StrictMode>
81→);
